/opt/homebrew/bin/zsh -lc "sed -n '4721,4748p;4376,4405p;4221,4240p' docs/DECISIONS-log.md; python3 -B -c 'import json,glob; fs=glob.glob(\"poc/data/clean-unlisted-probe-a3-2026-11-16/changed/send-*/outcomes.jsonl\");
for f in fs:
 for ln in open(f):
  x=json.loads(ln); case=x.get(\"case\", \"\");
  if any(a in case for a in [\"fortnight:c1/clean-6\", \"fortnight:c1/clean-12\", \"fortnight:c1/clean-3\", \"fortnight:c1/clean-7\"]):
   lad=(x.get(\"answer\") or {}).get(\"ladder\") or {}; print(f,case,\"parts\",[z.get(\"part\") for z in lad.get(\"not_judged\",[])],\"out\",lad.get(\"event\"))'"

